alter procedure dbo.sp_tStudent_insertUpdate      
@id int,      
@xYear int,      
@xPaye int ,      
@xClass int ,      
@Code bigint ,      
@FName nvarchar(100),      
@LName nvarchar(100),      
@PName nvarchar(100),      
@Sh_Sh nvarchar(200),      
@bDate nvarchar(10),      
@MobileFather nvarchar(11),      
@MobileMother nvarchar(11),      
@NumberTelegram nvarchar(11),      
@NumberTelegram2 nvarchar(11),      
@Jens smallint,      
@Mazhab smallint,      
@NumberAsas int ,      
@RegDate nvarchar(10),      
@Adress nvarchar (200),      
@ExitDate nvarchar(10),      
@Status smallint,      
      
@shaghe bit,      
@hazer bit,      
@mali bit,      
