                      @Fee1,@Fee2,@Fee3,@Fee4, @Fee5,@Fee6,@Fee7,@Fee8,@Fee9,@SumFee, @xTakhfif, 
      @transport1,@transport2,@transport3,@transport4, @transport5,  
                    @transport6,@transport7,@transport8,@transport9,@Sumtransport)    
  end    
    
    
    
  
  


